/**
 * Crow Tax — uploaded documents encrypted at rest (recovery keys, queue item 30, 2026-10-16).
 *
 * A W-2 or 1099 holds SSNs and income. Uploads are stored encrypted with the tax key
 * (CROW_TAX_ENCRYPTION_KEY, generated by Crow and saved in the keychain):
 *   "CROWTAXDOC1\n" + keyId(8) + salt(16) + iv(12) + tag(16) + AES-256-GCM ciphertext
 *   key   = PBKDF2-SHA256(passphrase, salt, 100k) — the same derivation as crypto.js
 *   keyId = HMAC-SHA256(that derived key, "crow-tax-document-key-id")[0..8] — says WHICH
 *           key sealed a file, so a wrong key is detected before anything is replaced. It
 *           comes from the salted PBKDF2 output, so it offers no cheaper offline guess
 *           check than the ciphertext itself, and it differs per file.
 *
 * Files stored before this change are plain PDFs. encryptStoredDocuments() moves them one
 * row at a time and never deletes a byte it has not verified:
 *   read → encrypt → write a private temp file + fsync → rename to a name unique to this
 *   run (<path>.<rand>.enc) → read back + decrypt + compare → compare-and-swap the row's
 *   file_path → only then unlink the plain file (and fsync the folder).
 * A lost swap removes only this run's own .enc. A crash leaves the plain file plus at most a
 * stray .enc; a crash after the swap leaves a plain sibling, which the next run removes once
 * the .enc it points to is verified. Runs (the panel at boot, the CLI) hold an exclusive lock
 * file in the documents folder, so two migrators never interleave.
 * decryptStoredDocuments() is the inverse (in place), or writes plain copies to a folder
 * without touching the database. Only regular files inside the documents folder(s) are ever
 * read, written or removed: a file_path from the database pointing anywhere else (or a
 * symlink) is skipped and reported by row id.
 */
import { createCipheriv, createDecipheriv, createHmac, randomBytes, pbkdf2 } from "node:crypto";
import { promisify } from "node:util";
import { openSync, writeSync, fsyncSync, closeSync, renameSync, readFileSync, unlinkSync, existsSync, lstatSync, realpathSync, mkdirSync, statSync, readdirSync, utimesSync, chmodSync } from "node:fs";
import { join, dirname, basename, resolve, sep } from "node:path";
import { homedir } from "node:os";
import { isExampleKey } from "./crypto.js";

const pbkdf2Async = promisify(pbkdf2);
export const MAGIC = Buffer.from("CROWTAXDOC1\n", "utf8");
const KID = 8, SALT = 16, IV = 12, TAG = 16, KEYLEN = 32, ITER = 100000;
const HEADER = MAGIC.length + KID + SALT + IV + TAG;
const LOCK_STALE_MS = 30 * 60 * 1000;
const ENC_NAME = /\.[0-9a-f]{8}\.enc$/;
const ENC_SUFFIX_LEN = ".00000000.enc".length;

/** This instance's documents folder (CROW_HOME: co-hosted instances each have their own). */
export function taxDocsDir(env = process.env) {
  return join(env.CROW_HOME || join(homedir(), ".crow"), "tax-documents");
}
/** Where every instance stored uploads before 2026-10 (it ignored CROW_HOME). */
export function legacyTaxDocsDir() {
  return join(homedir(), ".crow", "tax-documents");
}

const kidOf = (derived) => createHmac("sha256", derived).update("crow-tax-document-key-id").digest().subarray(0, KID);

export function isEncryptedDocument(buf) {
  return Buffer.isBuffer(buf) && buf.length >= HEADER && buf.subarray(0, MAGIC.length).equals(MAGIC);
}

function usable(passphrase) {
  if (!passphrase) throw new Error("CROW_TAX_ENCRYPTION_KEY is not set: documents cannot be stored encrypted.");
  if (isExampleKey(passphrase)) throw new Error("CROW_TAX_ENCRYPTION_KEY is the example value published in Crow's repository; documents are never stored with it.");
}

export async function encryptDocument(plain, passphrase) {
  usable(passphrase);
  const salt = randomBytes(SALT);
  const iv = randomBytes(IV);
  const derived = await pbkdf2Async(passphrase, salt, ITER, KEYLEN, "sha256");
  const c = createCipheriv("aes-256-gcm", derived, iv);
  const ct = Buffer.concat([c.update(plain), c.final()]);
  return Buffer.concat([MAGIC, kidOf(derived), salt, iv, c.getAuthTag(), ct]);
}

function parts(buf) {
  let o = MAGIC.length;
  const kid = buf.subarray(o, o += KID), salt = buf.subarray(o, o += SALT), iv = buf.subarray(o, o += IV), tag = buf.subarray(o, o += TAG);
  return { kid, salt, iv, tag, ct: buf.subarray(o) };
}

/** The passphrase (of `passphrases`) that sealed this file, and its derived key; or null. */
async function sealing(buf, passphrases) {
  if (!isEncryptedDocument(buf)) return null;
  const { kid, salt } = parts(buf);
  for (const p of (passphrases || []).filter(Boolean)) {
    const derived = await pbkdf2Async(p, salt, ITER, KEYLEN, "sha256");
    if (kidOf(derived).equals(kid)) return { passphrase: p, derived };
  }
  return null;
}
export async function sealedWith(buf, passphrases) {
  return (await sealing(buf, passphrases))?.passphrase || null;
}

export async function decryptDocument(buf, passphrases) {
  if (!isEncryptedDocument(buf)) throw new Error("not an encrypted tax document");
  const k = await sealing(buf, Array.isArray(passphrases) ? passphrases : [passphrases]);
  if (!k) throw new Error("this document was stored with a different tax key (not the current or previous one)");
  const { iv, tag, ct } = parts(buf);
  const d = createDecipheriv("aes-256-gcm", k.derived, iv);
  d.setAuthTag(tag);
  return { plain: Buffer.concat([d.update(ct), d.final()]), passphrase: k.passphrase };
}

function fsyncDir(dir) {
  try { const fd = openSync(dir, "r"); try { fsyncSync(fd); } finally { closeSync(fd); } } catch { /* best-effort */ }
}

/** Crash-safe private write: temp (0600, exclusive) → fsync → rename → fsync the folder. */
export function writePrivateAtomic(path, buf) {
  mkdirSync(dirname(path), { recursive: true, mode: 0o700 });
  const tmp = join(dirname(path), `.${basename(path)}.tmp-${process.pid}-${randomBytes(4).toString("hex")}`);
  const fd = openSync(tmp, "wx", 0o600);
  try { writeSync(fd, buf); fsyncSync(fd); } finally { closeSync(fd); }
  renameSync(tmp, path);
  fsyncDir(dirname(path));
}

/** The path, when it is a regular file (not a symlink) whose real location is inside one of `dirs`. */
export function storedDocumentPath(p, dirs) {
  if (typeof p !== "string" || !p) return null;
  const abs = resolve(p);
  for (const d of dirs) {
    let root;
    try { root = realpathSync(d); } catch { continue; }
    if (!abs.startsWith(resolve(d) + sep) && !abs.startsWith(root + sep)) continue;
    try {
      if (!lstatSync(abs).isFile()) return null;
      return realpathSync(abs).startsWith(root + sep) ? abs : null;
    } catch { return null; }
  }
  return null;
}

/**
 * A row's file. Fallbacks, for a crow.db restored from a backup: the same name in this
 * instance's folder (restored under another CROW_HOME); and, when the row still names the
 * plain file a later run migrated, that file's single encrypted successor <name>.<8hex>.enc
 * (in its own folder or this one). The caller swaps the row to whatever is found.
 */
function resolveRowFile(p, dirs) {
  const direct = storedDocumentPath(p, dirs);
  if (direct) return direct;
  if (typeof p !== "string" || !p) return null;
  const name = basename(p);
  const here = storedDocumentPath(join(dirs[0], name), dirs);
  if (here) return here;
  if (ENC_NAME.test(name)) return null;
  for (const d of [dirname(resolve(p)), dirs[0]]) {
    let list = [];
    try { list = readdirSync(d).filter((f) => f.startsWith(name + ".") && ENC_NAME.test(f) && f.slice(0, -ENC_SUFFIX_LEN) === name); } catch { continue; }
    if (list.length === 1) { const hit = storedDocumentPath(join(d, list[0]), dirs); if (hit) return hit; }
  }
  return null;
}

/**
 * Exclusive lock in the documents folder (also tightens the folder to 0700). A lock not
 * touched for 30 minutes is stale: it is taken over by an atomic rename, which only one
 * contender can win. The holder touches it as it goes (`touch`).
 */
function withLock(dir) {
  mkdirSync(dir, { recursive: true, mode: 0o700 });
  try { chmodSync(dir, 0o700); } catch { /* not ours to change */ }
  const lock = join(dir, ".documents.lock");
  const take = () => { const fd = openSync(lock, "wx", 0o600); closeSync(fd); };
  try {
    take();
  } catch {
    try {
      if (Date.now() - statSync(lock).mtimeMs < LOCK_STALE_MS) return null;
      const aside = `${lock}.stale-${process.pid}-${randomBytes(4).toString("hex")}`;
      renameSync(lock, aside); // ENOENT for every contender but one
      unlinkSync(aside);
      take();
    } catch { return null; }
  }
  const release = () => { try { unlinkSync(lock); } catch {} };
  release.touch = () => { try { const t = new Date(); utimesSync(lock, t, t); } catch {} };
  return release;
}

async function swapPath(db, id, from, to) {
  const r = await db.execute({ sql: "UPDATE tax_documents SET file_path = ? WHERE id = ? AND file_path = ?", args: [to, id, from] });
  return Number(r.rowsAffected ?? r.changes ?? 0) > 0;
}



/**
 * Move every plain stored document to its encrypted form (and re-encrypt one only the
 * previous key opens). Idempotent. Returns { encrypted, reencrypted, cleaned, skipped, errors, locked }.
 */
export async function encryptStoredDocuments(db, { key, previous = null, docsDirs = [taxDocsDir(), legacyTaxDocsDir()] } = {}) {
  const out = { encrypted: 0, reencrypted: 0, cleaned: 0, skipped: 0, errors: [], locked: false };
  if (!key) return { ...out, errors: ["CROW_TAX_ENCRYPTION_KEY is not set"] };
  try { usable(key); } catch (err) { return { ...out, errors: [err.message] }; }
  let rows;
  try { rows = (await db.execute("SELECT id, file_path FROM tax_documents")).rows; } catch { return out; }
  const release = withLock(docsDirs[0]);
  if (!release) return { ...out, locked: true };
  try {
    for (const r of rows) {
      release.touch();
      const p = resolveRowFile(r.file_path, docsDirs);
      if (!p) { out.skipped++; continue; }
      try {
        const buf = readFileSync(p);
        if (isEncryptedDocument(buf)) {
          // Found by a fallback (a restored crow.db): point the row at it.
          if (p !== resolve(r.file_path) && (await swapPath(db, r.id, r.file_path, p))) r.file_path = p;
          const { plain, passphrase } = await decryptDocument(buf, [key, previous]);
          // A crash after the swap left the plain original next to it: remove it once the
          // .enc is verified to hold exactly those bytes.
          const sibling = ENC_NAME.test(p) ? storedDocumentPath(p.replace(ENC_NAME, ""), docsDirs) : null;
          if (sibling && readFileSync(sibling).equals(plain)) { unlinkSync(sibling); fsyncDir(dirname(sibling)); out.cleaned++; }
          if (passphrase === key) { out.skipped++; continue; }
          const next = await encryptDocument(plain, key);
          if (!(await decryptDocument(next, [key])).plain.equals(plain)) throw new Error("verification failed");
          writePrivateAtomic(p, next);
          out.reencrypted++;
          continue;
        }
        const target = `${p.replace(ENC_NAME, "")}.${randomBytes(4).toString("hex")}.enc`;
        writePrivateAtomic(target, await encryptDocument(buf, key));
        if (!(await decryptDocument(readFileSync(target), [key])).plain.equals(buf)) { unlinkSync(target); throw new Error("verification failed"); }
        if (!(await swapPath(db, r.id, r.file_path, target))) { unlinkSync(target); out.skipped++; continue; }
        unlinkSync(p);
        fsyncDir(dirname(p));
        out.encrypted++;
      } catch (err) {
        out.errors.push(`document ${r.id}: ${err.message}`);
      }
    }
  } finally { release(); }
  return out;
}

/**
 * The inverse. inPlace: plain file written + verified, row swapped back, .enc removed
 * (for a downgrade: set CROW_TAX_KEEP_PLAIN_DOCUMENTS=1 first, or the next start encrypts
 * them again). Otherwise plain copies go to outDir (0700, files 0600), database untouched.
 */
export async function decryptStoredDocuments(db, { keys, inPlace = false, outDir = null, docsDirs = [taxDocsDir(), legacyTaxDocsDir()] } = {}) {
  const out = { decrypted: 0, skipped: 0, errors: [], locked: false };
  if (!inPlace && !outDir) throw new Error("choose inPlace or outDir");
  const rows = (await db.execute("SELECT id, filename, file_path FROM tax_documents")).rows;
  const release = inPlace ? withLock(docsDirs[0]) : () => {};
  if (!release) return { ...out, locked: true };
  try {
    for (const r of rows) {
      const p = resolveRowFile(r.file_path, docsDirs);
      if (!p) { out.skipped++; continue; }
      try {
        const buf = readFileSync(p);
        if (!isEncryptedDocument(buf)) { out.skipped++; continue; }
        const { plain } = await decryptDocument(buf, keys);
        if (inPlace) {
          const target = ENC_NAME.test(p) ? p.replace(ENC_NAME, "") : p.endsWith(".enc") ? p.slice(0, -4) : `${p}.pdf`;
          if (existsSync(target)) throw new Error(`${basename(target)} already exists`);
          writePrivateAtomic(target, plain);
          if (!readFileSync(target).equals(plain)) { unlinkSync(target); throw new Error("verification failed"); }
          if (!(await swapPath(db, r.id, r.file_path, target))) { unlinkSync(target); out.skipped++; continue; }
          unlinkSync(p);
        } else {
          const name = `${r.id}-${String(r.filename || "document.pdf").replace(/[^a-zA-Z0-9._-]/g, "_")}`;
          mkdirSync(outDir, { recursive: true, mode: 0o700 });
          try { chmodSync(outDir, 0o700); } catch { /* not ours */ }
          writePrivateAtomic(join(outDir, name), plain);
        }
        out.decrypted++;
      } catch (err) {
        out.errors.push(`document ${r.id}: ${err.message}`);
      }
    }
  } finally { release(); }
  return out;
}
